50. 다음의 코드에 적용된 설계 원리로 가장 거리가
먼 것은?
class Data {
int v1, v2 ;
public:
Data(int _v1, int _v2 ) { v1 = _v1 ; v2 = _v2 ; }
int runWith(int x) { return v1 + v2 + x ; }
bool check(int x) { return x > v1 + v2 ; }
} ;
int f1(int x, Data d) {
bool success = d.check(x) ;
int result = 0 ;
if ( success )
result = d.runWith(x) ;
return result ;
}

