42. 프로그래머 A는 성적처리 함수를 작성하려고 한다. 
프로그래머 A가 else-if 구조의 printGrade1(int) 함수와 
switch 구조의 printGrade2(int) 함수로 두 가지 버전의 
코드를 작성하여 실행해 보았다. 이 두 코드의 수행 
결과값이 달라지는 입력값으로 가장 적합한 것은? 
void printGrade1 ( int score) {
    char res;
    if ( score >= 90 )
       res = ‘A’ ;
    else if ( score >= 80 )
       res = ‘B’ ;
    else if ( score >= 60 )
       res = ‘D’ ;
    else if ( score >= 70 )
       res = ‘C’ ;
    else
       res = ‘F’;
    putchar ( res );
}
void printGrade2 ( int score) {
    char res;
    switch ( score/10 ) {
       case 10:  case 9:
            res = ‘A’; break;
       case 8:
            res = ‘B’; break;
       case 6:
            res = ‘D’; break;
       case 7:
            res = ‘C’; break;
       default:
            res = ‘F’;
    }
    putchar ( res );
}
